import{I as a,c as o,d as t,O as d}from"./chunks/framework.N7KwZWfa-ghp20261122.js";const p=JSON.parse('{"title":"少女迴戰 MOD｜客戶端修改與官方皮膚","titleTemplate":false,"description":"瞭解少女迴戰 MOD 常指的立繪或模型替換、官方變裝的獲取方式，以及如何核對 iOS 和安卓原版客戶端來源。","frontmatter":{"title":"少女迴戰 MOD｜客戶端修改與官方皮膚","titleTemplate":false,"description":"瞭解少女迴戰 MOD 常指的立繪或模型替換、官方變裝的獲取方式，以及如何核對 iOS 和安卓原版客戶端來源。","breadcrumbs":[["/download/","遊戲下載"]],"breadcrumbLabel":"MOD 與官方皮膚","lastmod":"2026-11-16"},"headers":[],"relativePath":"download/mod/index.md","filePath":"download/mod/index.md"}'),l={name:"download/mod/index.md"};function i(n,e,r,c,s,h){return o(),t("div",null,[...e[0]||(e[0]=[d('<article class="page-shell knowledge-page reference-guide"><h1 id="少女迴戰-mod-與官方皮膚" tabindex="-1">少女迴戰 MOD 與官方皮膚 <a class="header-anchor" href="#少女迴戰-mod-與官方皮膚" aria-label="Permalink to &quot;少女迴戰 MOD 與官方皮膚&quot;">​</a></h1><p>MOD 通常指玩家修改的遊戲檔案。在少女迴戰的玩家討論裡，常見用法是替換本機的立繪或模型。官方皮膚在遊戲裡歸入「變裝」，按對應武將和形態檢視名稱、取得條件與互動。</p><h2 id="武將皮膚和互動在哪裡看" tabindex="-1">武將皮膚和互動在哪裡看 <a class="header-anchor" href="#武將皮膚和互動在哪裡看" aria-label="Permalink to &quot;武將皮膚和互動在哪裡看&quot;">​</a></h2><p>在<a href="/zh-hant/skins/">皮膚圖鑑</a>按角色名查詢。點皮膚圖片可直接開啟該變裝的立繪，有互動的形態可點選畫面上的觸控點播放動作與語音。點卡片下方的「變裝資料」可檢視對應武將頁面已收錄的獲取方式。</p><h2 id="怎樣核對原版客戶端" tabindex="-1">怎樣核對原版客戶端 <a class="header-anchor" href="#怎樣核對原版客戶端" aria-label="Permalink to &quot;怎樣核對原版客戶端&quot;">​</a></h2><ol><li>在<a href="/zh-hant/download/">官方商店下載頁</a>選擇遊玩的區服和裝置，核對商店顯示的開發者 ONEMT。</li><li>安卓可對照 Google Play 網址裡的應用識別碼。日服為 <code>com.onemt.and.shoujokaisen</code>，繁中服為 <code>com.onemt.and.shtwn</code>。</li><li>iPhone 與 iPad 可對照 App Store 應用編號。日服為 <code>1550427034</code>，繁中服為 <code>1587828931</code>。</li></ol><p>需要重新安裝原版時，先確認角色的賬號繫結、UID 和伺服器名稱，再從對應商店取得應用並選回原服。</p></article>',1)])])}const _=a(l,[["render",i]]);export{p as __pageData,_ as default};
